61	         reg {
62	            name = "csr.cpu_fifo.rx.data_31_0";
63	            desc = "Rx FIFO Data Register";
64	
65	            field {
66	               name = "csr.cpu_fifo.rx.data_31_0.tdata[31:0]";
67	               desc = "1st 4-byte segment of TDATA, i.e. TDATA[31:0]";
68	               sw = rw;
69	               hw = r;
70	            } tdata[32] = 0;
71	         } data_31_0;
