105	               hw = r;
106	            } tdata[32] = 0;
107	         } data_127_96;
108	
109	         reg {
110	            name = "csr.cpu_fifo.rx.control";
111	            desc = "Rx FIFO Control Register";
112	
113	            field {
114	               name = "csr.cpu_fifo.rx.control.tkeep[15:0]";
115	               desc = "Byte-enable for TDATA (e.g. TKEEP[15] corresponds to TDATA[127:119])";
116	               sw = rw;
117	               hw = r;
118	            } tkeep[31:16] = 0;
119	
120	            field {
121	               name = "csr.cpu_fifo.rx.control.tlast";
122	               desc = "Indicates boundary of a packet, i.e. active on last transfer";
123	               sw = rw;
124	               hw = r;
125	            } tlast[15:15] = 0;
126	
127	            field {
128	               name = "csr.cpu_fifo.rx.control.tuser_bypass_all";
129	               desc = "DPE is bypassed when active";
130	               sw = rw;
131	               hw = r;
132	            } tuser_bypass_all[7:7] = 0;
133	
134	            field {
135	               name = "csr.cpu_fifo.rx.control.tuser_bypass_stage";
136	               desc = "Next stage of the DPE is bypassed when active";
137	               sw = rw;
138	               hw = r;
139	            } tuser_bypass_stage[6:6] = 0;
140	
141	            field {
142	               name = "csr.cpu_fifo.rx.control.tuser_src[2:0]";
143	               desc = "Internal source address (0 - CPU, 1 - eth1, 2 - eth2, 3 - eth3, 4 - eth4)";
144	               sw = rw;
145	               hw = r;
146	            } tuser_src[5:3] = 0;
147	
148	            field {
149	               name = "csr.cpu_fifo.rx.control.tuser_dst[2:0]";
150	               desc = "Internal destination address (0 - CPU, 1 - eth1, 2 - eth2, 3 - eth3, 4 - eth4, 7 - broadcast)";
151	               sw = rw;
152	               hw = r;
153	            } tuser_dst[2:0] = 0;
154	         } control;
155	
156	         reg {
157	            name = "csr.cpu_fifo.rx.trigger";
158	            desc = "Rx FIFO Trigger Register";
159	
160	            field {
161	               name = "csr.cpu_fifo.rx.trigger.tvalid";
162	               desc = "Indicates valid transfer from the CPU to the Rx FIFO (single pulse trigger)";
163	               singlepulse = true;
164	               sw = rw;
165	               hw = r;
166	            } tvalid = 0;
167	         } trigger;
168	
169	         reg {
170	            name = "csr.cpu_fifo.rx.status";
171	            desc = "Rx FIFO Status Register";
172	
173	            field {
174	               name = "csr.cpu_fifo.rx.status.tready";
175	               desc = "Indicates that the Rx FIFO can accept a transfer";
176	               sw = r;
177	               hw = w;
178	            } tready = 0;
179	         } status;
180	      } rx;
