312	      reg {
313	         name = "csr.uart.rx";
314	         desc = "UART Rx Register";
315	
316	         field {
317	            name = "csr.uart.rx.valid";
318	            desc = "Indicates valid data transfer from the UART to the CPU";
319	            sw = r;
320	            hw = w;
321	         } valid[31:31] = 0;
322	
323	         field {
324	            name = "csr.uart.rx.oflow";
325	            desc = "Indicates that some data bytes are lost";
326	            sw = r;
327	            hw = w;
