329	
330	         field {
331	            name = "csr.uart.rx.data[7:0]";
332	            desc = "Received data";
333	            sw = r;
334	            hw = w;
335	            swacc = true;
336	         } data[7:0] = 0;
337	      } rx;
338	
339	      reg {
340	         name = "csr.uart.rx_trigger";
341	         desc = "UART Rx Trigger Register";
342	
343	         field {
344	            name = "csr.uart.rx_trigger.read";
345	            desc = "Indicates that the CPU can accept next data transfer, used internally - don't try to read or write!";
346	         } read = 0;
347	      } rx_trigger;
348	
349	      rx_trigger.read->next = rx.data->swacc;
350	
351	      reg {
352	         name = "csr.uart.tx";
353	         desc = "UART Tx Register";
354	
355	         field {
356	            name = "csr.uart.tx.busy";
357	            desc = "Indicates that UART cannot accept next data transfer";
358	            sw = r;
359	            hw = w;
360	         } busy[31:31] = 0;
361	
362	         field {
363	            name = "csr.uart.tx.data[7:0]";
364	            desc = "Data to send";
365	            sw = rw;
366	            hw = r;
367	            swmod = true;
368	         } data[7:0] = 0;
369	      } tx;
370	
371	      reg {
372	         name = "csr.uart.tx_trigger";
373	         desc = "UART Tx Trigger Register";
374	
375	         field {
376	            name = "csr.uart.tx_trigger.write";
377	            desc = "Indicates valid data transfer from the CPU to the UART, used internally - don't try to read or write!";
378	         } write = 0;
379	      } tx_trigger;
380	
381	      tx_trigger.write->next = tx.data->swmod;
382	   } uart;
